#!/bin/sh
# Generated by forge. PreToolUse(Bash) tripwire: matches guard.rules patterns
# (POSIX ERE) against the JSON-escaped command. First deny wins, else first ask.
# The sandbox and permissions are the protection boundary; this is a tripwire.
# An ask nobody can answer (an autonomous run) goes to review.sh instead.
dir=$(dirname "$0")
input=$(cat)
out=$(printf '%s' "$input" | awk -F '\t' -v rules="$dir/guard.rules" '
  { buf = buf $0 " " }
  END {
    if (!match(buf, /"command"[[:space:]]*:[[:space:]]*"/)) exit 0
    s = substr(buf, RSTART + RLENGTH); n = length(s); cmd = ""
    for (i = 1; i <= n; i++) {
      c = substr(s, i, 1)
      if (c == "\"") break
      if (c == "\\") { cmd = cmd c substr(s, i + 1, 1); i++; continue }
      cmd = cmd c
    }
    while ((getline line < rules) > 0) {
      if (line ~ /^#/ || line == "") continue
      split(line, f, "\t")
      if (f[2] == "deny" && cmd ~ f[3]) { hit("deny", f[1], f[4]); exit 0 }
      if (f[2] == "ask" && ask == "" && cmd ~ f[3]) { ask = f[1]; askd = f[4] }
    }
    if (ask != "") hit("ask", ask, askd)
  }
  function hit(decision, id, desc) {
    gsub(/\\/, "\\\\", desc); gsub(/"/, "\\\"", desc)
    printf "{\"hookSpecificOutput\":{\"hookEventName\":\"PreToolUse\",\"permissionDecision\":\"%s\",\"permissionDecisionReason\":\"forge:%s %s\"}}\n", decision, id, desc
  }
') || exit 1
case $out in
  *'"permissionDecision":"ask"'*)
    if [ -z "${FORGE_REVIEWER:-}" ] && [ "${FORGE_ASK_REVIEW:-auto}" != never ] && [ -f "$dir/review.sh" ]; then
      rule=${out#*'"permissionDecisionReason":"forge:'}
      reviewed=$(printf '%s' "$input" | sh "$dir/review.sh" pre "${rule%% *}")
      [ -n "$reviewed" ] && out=$reviewed
    fi ;;
esac
[ -z "$out" ] || printf '%s\n' "$out"
